sysevent_script_action.script:
var assigned_to = current.getValue('assigned_to');
var ag = current.getValue('assignment_group');
var num = current.getValue('number');
var grEmail = null;
gs.info('Puru Debug: assigned_to=' + assigned_to);
gs.info('Debug: assignment_group=' + ag);
gs.info('Debug: number=' + num);

//Mail body starts
    var bodyContent = '<div style="font-family: calibri;"><p>Hi Team,</p></div><div style="font-family: calibri;"><p>Please refer to the below PRM form information.</p></div>';

    // Table Header
    var tradeBody = '<table style="border: 1px solid black; border-collapse: collapse;font-size:12px;table-layout:Fixed; width: 100%;text-align:left;font-family: calibri;"><tbody style="border: 1px solid black; border-collapse: collapse;font-size:12px;table-layout:Fixed; width: 100%;text-align:left;font-family: calibri;" ><tr style="background-color: #b22222; text-align:left">';
    var col1 = '<th style="border: 1px solid black;color: #FFFFFF;text-align:left;">Number</th>';
    var col2 = '<th style="border: 1px solid black;color: #FFFFFF;text-align:left;">State</th>';
    var col3 = '<th style="border: 1px solid black;color: #FFFFFF;text-align:left;">Assigned To</th>';
    var col4 = '<th style="border: 1px solid black;color: #FFFFFF;text-align:left;">Assignment Group</th>';
    var col5 = '<th style="border: 1px solid black;color: #FFFFFF;text-align:left;">Country</th>';
    var col6 = '<th style="border: 1px solid black;color: #FFFFFF;text-align:left;">Region</th>';
    var col7 = '<th style="border: 1px solid black;color: #FFFFFF;text-align:left;">Form Type</th>';

    // Table Row
    var r1 = '</tr><tr><td style="border: 1px solid black;">' + current.number + '</td>';
    var r2 = '<td style="border: 1px solid black;">' + current.state.getDisplayValue() + '</td>';
    var r3 = '<td style="border: 1px solid black;">' + current.assigned_to.getDisplayValue() + '</td>';
    var r4 = '<td style="border: 1px solid black;">' + current.assignment_group.getDisplayValue() + '</td>';
    var r5 = '<td style="border: 1px solid black;">' + current.country + '</td>';
    var r6 = '<td style="border: 1px solid black;">' + current.region + '</td>';
    var r7 = '<td style="border: 1px solid black;">' + current.form_type + '</td>';

    // Table End
    var tradeBody_end = '</tbody></table><style>table, th, td { border-collapse: collapse;table-layout:Fixed; text-align:left;font-size:14px;font-family: calibri;}table,th{color: #FFFFFF;}table,td{color: #000000;}#td1{background-color: #ffff31;}div{font-family: calibri;}</style><br>&nbsp';

    // Combine Header, Columns, and Rows
    var body_col = tradeBody + col1 + col2 + col3 + col4 + col5 + col6 + col7;
    var body_row = r1 + r2 + r3 + r4 + r5 + r6 + r7 + tradeBody_end;
    var body = body_col + body_row;

//Mail Body ends

function sendMail(body,grEmail) {
    try {
        var inputs = {};
        inputs['torecipients'] = 'HSSQTrack140@adrestest.addev.hsbc'; // String
        inputs['ccrecipients'] = assigned_to; // String
        inputs['emlsender'] = 'HSSQTrack140@adrestest.addev.hsbc'; // String
        inputs['emlsubject'] = 'Test PRM Notification'; // String
        inputs['bccrecipients'] = ''; // String
        inputs['emlbody'] = body; // String
        inputs['classification'] = 'restricted'; // String
        inputs['servicenowid'] = 'na'; // String
        gs.info('Puru Debug: Inputs object=' + JSON.stringify(inputs));
		gs.info('Puru Debug: Email body=' + body);
        // Execute Synchronously: Run in foreground. Code snippet has access to outputs.
        var result = sn_fd.FlowAPI.getRunner().action('x_hsb11_hsbcmss_qw.qtrack_action').inForeground().withInputs(inputs).run();
        var outputs = result.getOutputs();
        gs.info(' Puru Debug: Outputs=' + JSON.stringify(outputs));
    } catch (ex) {
        var message = ex.getMessage();
        gs.error('Error: ' + message);
    }
}
// Call the function for testing
sendMail(body,grEmail);
